import {nearestRoad} from './levels.js';
import {TOWERS,statsFor} from './towers.js';
const PALETTE={grass:['#35432b','#35412b','#37452d','#3b482f','#32412c'],road:'#796f48',edge:'#4b5132'};
const spriteCache=new Map();let sheets={};
export async function loadArt(){await Promise.all(['tiny-town','tiny-dungeon'].map(pack=>new Promise(resolve=>{const im=new Image();im.onload=()=>{sheets[pack]=im;resolve();};im.onerror=()=>resolve();im.src=new URL(`../assets/${pack}/Tilemap/tilemap.png`,import.meta.url).href;})));}
function sprite(ctx,pack,id,x,y,scale=1,tint){const sheet=sheets[pack];if(!sheet)return;const key=pack+id+tint;let source=spriteCache.get(key);if(!source){source=document.createElement('canvas');source.width=source.height=16;const c=source.getContext('2d');c.drawImage(sheet,(id%12)*17,Math.floor(id/12)*17,16,16,0,0,16,16);if(tint){c.globalCompositeOperation='source-atop';c.globalAlpha=.36;c.fillStyle=tint;c.fillRect(0,0,16,16);}spriteCache.set(key,source);}ctx.drawImage(source,Math.round(x),Math.round(y),16*scale,16*scale);}
function rect(c,color,x,y,w,h){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),w,h);}
function rng(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
function road(c,points,width,color){c.beginPath();c.moveTo(...points[0]);for(const p of points.slice(1))c.lineTo(...p);c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.strokeStyle=color;c.stroke();}
export function createTerrain(g){const canvas=document.createElement('canvas');canvas.width=480;canvas.height=288;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const rand=rng(889+g.levelIndex*45),pine=g.level.region===1,ash=g.level.region===2;for(let y=0;y<288;y+=4)for(let x=0;x<480;x+=4)rect(c,PALETTE.grass[Math.floor(rand()*5)],x,y,4,4);
// A shallow stream cuts through the farm and vanishes beneath the road.
const stream=[[297,-10],[293,32],[311,64],[312,116],[302,151],[315,187],[300,230],[292,299]];road(c,stream,24,'#293c33');road(c,stream,18,'#3e5142');road(c,stream,12,'#425849');for(let i=0;i<100;i++){const x=288+rand()*35,y=rand()*288;if(nearestRoad({segments:stream.slice(1).map((p,i)=>({a:stream[i],b:p,len:Math.hypot(p[0]-stream[i][0],p[1]-stream[i][1]),start:0}))},x,y).distance<8)rect(c,'#6c7b58',x,y,3+Math.floor(rand()*5),1);}
road(c,g.level.path,29,'#293725');road(c,g.level.path,25,'#56603b');road(c,g.level.path,21,'#8a7f50');road(c,g.level.path,17,'#82754a');road(c,g.level.path,12,'#877b50');for(let i=0;i<2000;i++){const x=rand()*480,y=rand()*288,n=nearestRoad(g.path,x,y);if(n.distance<10)rect(c,rand()>.5?'#9b8c5b':'#706944',x,y,rand()>.7?2:1,1);else if(n.distance>18){rect(c,rand()>.5?'#53603b':'#293b28',x,y,2,1);if(rand()>.65)rect(c,'#58663d',x+1,y-2,1,2);}}
// Crops, broken fencing, tombstones, and actual Kenney village architecture.
for(const [fx,fy] of [[18,204],[147,17],[390,235]]){for(let y=0;y<28;y+=5){rect(c,'#4c4b2d',fx,fy+y,43,3);for(let x=0;x<42;x+=5)rect(c,'#6e7244',fx+x,fy+y-1,1,2);}for(let x=0;x<46;x+=16)sprite(c,'tiny-town',69,fx+x,fy+28,1,'#61613d');}
const structures=[[38,33],[146,242],[414,179]];for(const [x,y] of structures){rect(c,'#263222',x-4,y+9,49,33);for(let i=0;i<3;i++){sprite(c,'tiny-town',48+i,x+i*16,y,1,'#596052');sprite(c,'tiny-town',76+i,x+i*16,y+16,1,'#6c735c');}sprite(c,'tiny-town',89,x+16,y+16,1,'#736a4b');}
// The old mill's silhouette; blades are animated separately.
if(g.levelIndex===0){for(let j=0;j<3;j++)sprite(c,'tiny-dungeon',40,250,26+j*16,1,'#656957');sprite(c,'tiny-town',63,250,15,1,'#686850');}
for(let i=0;i<150;i++){const x=rand()*480,y=rand()*288;const open=nearestRoad(g.path,x+8,y+13).distance;const nearPlot=g.level.plots.some(([px,py])=>Math.hypot(px-x-8,py-y-8)<25);if(open<27||nearPlot||Math.hypot(x-450,y-67)<40)continue;if(i<115){const id=pine?4:[4,5,16,28][Math.floor(rand()*4)];sprite(c,'tiny-town',id,x,y,1,pine?'#234d43':'#3c4e2a');if(i%4===0)sprite(c,'tiny-town',pine?4:5,x-7,y+8,1,pine?'#234d43':'#3c4e2a');}else sprite(c,'tiny-dungeon',i%2?64:65,x,y,1,'#60694d');}
// Rampart framing the gate at the road endpoint.
const gateY=g.level.path.at(-1)[1];for(let y=0;y<288;y+=16){if(Math.abs(y-gateY)<19)continue;sprite(c,'tiny-town',109,454,y,1,'#69705b');sprite(c,'tiny-dungeon',40,470,y,1,'#69705b');}for(const y of [gateY-34,gateY+19]){sprite(c,'tiny-town',96,446,y,1,'#788067');sprite(c,'tiny-town',97,462,y,1,'#788067');sprite(c,'tiny-town',108,446,y+16,1,'#68705d');}rect(c,'#3c3828',461,gateY-11,14,24);for(let i=0;i<4;i++)rect(c,'#6d6550',462+i*4,gateY-11,2,24);
if(pine||ash){c.fillStyle=pine?'#17384430':'#4b313530';c.fillRect(0,0,480,288);}g.terrain=canvas;}
function ring(c,x,y,r,color,fill=false){c.beginPath();c.arc(Math.round(x),Math.round(y),r,0,Math.PI*2);if(fill){c.fillStyle=color;c.fill();}else{c.strokeStyle=color;c.lineWidth=1;c.stroke();}}
function tower(c,t,time){const color=TOWERS[t.type].color;rect(c,'#202a1c',t.x-13,t.y-5,26,13);sprite(c,'tiny-town',108,t.x-12,t.y-18,1,'#73765b');sprite(c,'tiny-town',110,t.x+4,t.y-18,1,'#73765b');sprite(c,'tiny-dungeon',40,t.x-4,t.y-18,1,'#6a7156');if(t.type==='archer'){sprite(c,'tiny-town',96,t.x-12,t.y-28,1,'#797756');sprite(c,'tiny-town',98,t.x+4,t.y-28,1,'#797756');sprite(c,'tiny-dungeon',112,t.x-4,t.y-33,1,'#72835a');}if(t.type==='barracks'){sprite(c,'tiny-town',64,t.x-12,t.y-26,1,'#796848');sprite(c,'tiny-town',66,t.x+4,t.y-26,1,'#796848');sprite(c,'tiny-town',89,t.x-4,t.y-12,1,'#7c7d65');}if(t.type==='artillery'){sprite(c,'tiny-town',107,t.x-8,t.y-24,1,'#a5754b');rect(c,'#ebb969',t.x-4,t.y-18,8,3);rect(c,'#f2da8e',t.x-2+Math.sin(time*5)*2,t.y-21,3,4);}if(t.type==='magic'){sprite(c,'tiny-dungeon',41,t.x-8,t.y-28,1,'#8f83a1');sprite(c,'tiny-dungeon',128,t.x-8,t.y-37,1,'#b89bc6');ring(c,t.x,t.y-29,6+Math.sin(time*3),color+'55');}for(let i=0;i<(t.branch?4:t.tier+1);i++)rect(c,'#d7be7d',t.x-7+i*5,t.y+8,3,2);}
function person(c,p,time,hero=false){const scale=p.scale||1,bob=p.air?Math.sin(time*3+p.id)*3:Math.sin(time*8+(p.id||0))*.6;c.globalAlpha=p.tunneling?.35:1;ring(c,p.x,p.y+4,hero?8:5,'#14231ba0',true);sprite(c,'tiny-dungeon',p.sprite,p.x-8*scale,p.y-12*scale+bob,scale,p.color||'#7d8b72');if(hero&&p.type==='bunny'){rect(c,'#e7cfbd',p.x-5,p.y-19,2,7);rect(c,'#e7cfbd',p.x+2,p.y-20,2,8);}if(hero){ring(c,p.x,p.y+3,10,'#decd81');rect(c,'#e0c583',p.x-1,p.y-20,3,2);}if(p.shield>0)ring(c,p.x,p.y-3,11,'#bfcab277');if(p.burn>0)rect(c,'#efaa55',p.x+3,p.y-5,3,5);if(p.curse>0)ring(c,p.x,p.y-8,10,'#bd93d4');if(p.hp<p.maxHP||hero||p.boss){rect(c,'#202820',p.x-8,p.y-16*scale,16,2);rect(c,hero?'#a6bf81':'#b67a5c',p.x-8,p.y-16*scale,Math.max(0,Math.ceil(16*p.hp/p.maxHP)),2);}c.globalAlpha=1;}
export function render(g,c){c.save();c.imageSmoothingEnabled=false;if(g.shake>0)c.translate(Math.round((Math.random()-.5)*g.shake),Math.round((Math.random()-.5)*g.shake));c.drawImage(g.terrain,0,0);const time=g.time;const selected=g.towers.find(t=>t.id===g.selection?.id&&g.selection.kind==='tower');if(selected||g.buildType&&g.hover){const p=selected||(g.hover.kind==='plot'?{x:g.level.plots[g.hover.index][0],y:g.level.plots[g.hover.index][1]}:null);if(p){const range=selected?statsFor(selected).range:TOWERS[g.buildType].tiers[0].range;ring(c,p.x,p.y,range,'#d9d39a13',true);c.setLineDash([3,3]);ring(c,p.x,p.y,range,'#c8ce8677');c.setLineDash([]);}}
for(let i=0;i<g.level.plots.length;i++){if(g.towers.some(t=>t.plot===i))continue;const [x,y]=g.level.plots[i],active=g.selection?.kind==='plot'&&g.selection.index===i||g.hover?.kind==='plot'&&g.hover.index===i;rect(c,'#283322',x-13,y-7,26,17);rect(c,active?'#a9a573':'#737c51',x-12,y-8,24,14);rect(c,active?'#73794c':'#525f3c',x-10,y-6,20,10);rect(c,active?'#e5d597':'#a1aa6d',x-4,y-1,8,2);rect(c,active?'#e5d597':'#a1aa6d',x-1,y-4,2,8);rect(c,'#90946a',x-12,y+6,3,3);rect(c,'#90946a',x+9,y+6,3,3);}
const objects=[...g.towers.map(t=>({y:t.y,draw:()=>tower(c,t,time)})),...g.enemies.map(e=>({y:e.y,draw:()=>person(c,e,time)})),...g.soldiers.filter(s=>s.hp>0).map(s=>({y:s.y,draw:()=>person(c,s,time)}))];if(g.hero.hp>0)objects.push({y:g.hero.y,draw:()=>person(c,g.hero,time,true)});objects.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());if(selected&&(selected.type==='barracks'||selected.branch==='soulforge')){c.setLineDash([2,3]);c.strokeStyle='#c9bf7c88';c.beginPath();c.moveTo(selected.x,selected.y);c.lineTo(selected.rally.x,selected.rally.y);c.stroke();c.setLineDash([]);flag(c,selected.rally.x,selected.rally.y,'#bea876',time);}if(g.banner){ring(c,g.banner.x,g.banner.y,72,'#d5bd6730',true);flag(c,g.banner.x,g.banner.y,'#e1c575',time);}for(const [x,y] of [[55,150],[193,81],[235,224],[367,77],[442,g.level.path.at(-1)[1]-17],[442,g.level.path.at(-1)[1]+17]]){rect(c,'#443c2a',x,y,2,9);const glow=c.createRadialGradient(x,y,1,x,y,23+Math.sin(time*8+x)*3);glow.addColorStop(0,'#fbb45142');glow.addColorStop(1,'#e8a04100');c.fillStyle=glow;c.fillRect(x-27,y-27,54,54);rect(c,'#e7a351',x-1,y-3,4,5);rect(c,'#f4d58a',x,y-5+(Math.floor(time*9)%2),2,5);}
if(g.levelIndex===0){c.save();c.translate(258,37);c.rotate(Math.sin(time*.15)*.5+time*.14);for(let i=0;i<4;i++){c.rotate(Math.PI/2);rect(c,'#282e24',-2,0,4,28);rect(c,'#a0a080',0,10,6,17);rect(c,'#687052',0,14,6,1);rect(c,'#687052',0,20,6,1);}c.restore();}
for(const fx of g.effects){c.globalAlpha=Math.min(1,fx.life*2);if(fx.type==='text'){c.font='bold 6px monospace';c.textAlign='center';c.fillStyle='#1c2519';c.fillText(fx.text,fx.x+1,fx.y+1);c.fillStyle=fx.color;c.fillText(fx.text,fx.x,fx.y);}if(fx.type==='ring'){ring(c,fx.x,fx.y,fx.r*(1-Math.min(.85,fx.life)),fx.color);ring(c,fx.x,fx.y,fx.r*.65,fx.color+'20',true);}if(fx.type==='bolt'){c.beginPath();c.moveTo(fx.x,fx.y);c.lineTo(fx.tx,fx.ty);c.strokeStyle=fx.color;c.lineWidth=1;c.stroke();}if(fx.type==='particle')rect(c,fx.color,fx.x,fx.y,2,2);c.globalAlpha=1;}
// Fog is deliberately sparse so units and health bars stay readable.
for(let i=0;i<5;i++){const x=((time*2+i*117)%650)-100,y=24+i*59;const fog=c.createRadialGradient(x,y,1,x,y,95);fog.addColorStop(0,'#d1d4b90b');fog.addColorStop(1,'#c9ceb300');c.fillStyle=fog;c.fillRect(x-95,y-50,190,100);}const vignette=c.createRadialGradient(240,144,110,240,144,300);vignette.addColorStop(0,'#07130f00');vignette.addColorStop(1,'#07130f88');c.fillStyle=vignette;c.fillRect(0,0,480,288);
if(g.targeting&&g.pointer){ring(c,g.pointer.x,g.pointer.y,g.targeting==='rally'?15:60,'#e4b774');}if(g.hover?.kind==='enemy'){const e=g.enemies.find(e=>e.id===g.hover.id);if(e){const x=Math.min(345,Math.max(5,e.x-40)),y=Math.max(27,e.y-40);rect(c,'#15231bee',x,y,128,23);c.font='6px monospace';c.fillStyle='#e6dec2';c.fillText(e.name,x+5,y+8);c.fillStyle='#a9b993';c.fillText(`${Math.ceil(e.hp)} HP · ${Math.round(e.armor*100)} ARM · ${Math.round(e.resist*100)} MR`,x+5,y+18);}}c.restore();}
function flag(c,x,y,color,time){rect(c,'#a6a485',x,y-24,1,26);rect(c,color,x+1,y-24,10,7);rect(c,color,x+10,y-23+Math.round(Math.sin(time*4)),3,6);}
